custom_css:
/* ══════════════════════════════════
   ☀️ iOS 液态玻璃 · Liquid Glass Day Edition v5.0
   日间版 · 奶白磨砂 · 柔光折射 · iOS 浅色美学
   作者: "小松鼠 & Claude Sonnet 4.6"
   允许: "改配色/改字体"
   禁止: "二传 & 商用"
══════════════════════════════════ */

@import url("https://fontsapi.zeoseven.com/670/main/result.css");

/* ══════════════════════════════════
   § 核心变量 — 日间浅色系
══════════════════════════════════ */
:root { --text1: '深度思考中...';
  --text2: '永远爱你是我说过...';

  /* 玻璃透明度层级 — 日间：白色磨砂感 */
  --glass-ultra: rgba(255,255,255,0.1);
  --glass-light: rgba(255,255,255,0.25);
  --glass-medium: rgba(255,255,255,0.5);
  --glass-strong: rgba(255,255,255,0.70);

  /* 玻璃边框 — 日间：细腻浅灰 */
  --gb-subtle: rgba(0,0,0,0.055);
  --gb-default: rgba(0,0,0,0.095);
  --gb-bright: rgba(0,0,0,0.160);

  /* 模糊强度 — iOS 26 超强模糊 */
  --blur-md: blur(22px);

  /* 系统色 — 日间略微提饱和，更清新 */
  --ios-blue: #4A85BB;
  --ios-blue-glass: rgba(74,133,187,0.12);
  --ios-blue-border: rgba(74,133,187,0.28);

  --ios-teal: #38A86C;
  --ios-teal-glass: rgba(56,168,108,0.12);
  --ios-teal-border: rgba(56,168,108,0.28);

  --ios-purple: #7B62A8;
  --ios-purple-glass: rgba(123,98,168,0.10);
  --ios-purple-border: rgba(123,98,168,0.24);

  /* 用户色 — 日间玫粉系 */
  --user-rose: #A0788A;

  /* 文字层级 — 日间深色文字 */
  --text-100: rgba(28,30,38,0.90);
  --text-70: rgba(28,30,38,0.62);
  --text-45: rgba(28,30,38,0.40);

  --crimson70a: #d3adf1;
  --font-main: 'Frex Sans GB VF', 'Microsoft YaHei', sans-serif; }

/* ══════════════════════════════════
   § 全局背景 — 日间云雾浅色
══════════════════════════════════ */
/* 字体*/
html,
body,
select,
textarea,
#send_textarea,
.name_text,
.mes_text,
.mes_reasoning {
  font-family: var(--font-main) !important;
  font-weight: normal;
}

html {
  background-color: var(--SmartThemeChatTintColor) !important;
  background: radial-gradient(ellipse 80% 55% at 10% 8%, rgba(200,218,240,0.70) 0%, transparent 55%), radial-gradient(ellipse 65% 50% at 88% 85%, rgba(210,200,235,0.55) 0%, transparent 48%), radial-gradient(ellipse 55% 60% at 50% 40%, rgba(220,235,248,0.45) 0%, transparent 58%), radial-gradient(ellipse 45% 40% at 25% 78%, rgba(190,230,215,0.40) 0%, transparent 42%), radial-gradient(ellipse 40% 38% at 76% 15%, rgba(215,225,245,0.50) 0%, transparent 38%), linear-gradient(168deg, #97A8D9 0%, #AFABCA 28%, #DED0DF 60%, #97A8D9 100%);
  background-attachment: fixed;
}

/* 日间光晕层 */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  background-image: radial-gradient(3px 3px at 15% 20%, rgba(255,255,255,0.90) 0%, transparent 100%), radial-gradient(2px 2px at 38% 10%, rgba(255,255,255,0.75) 0%, transparent 100%), radial-gradient(3px 3px at 70% 25%, rgba(255,255,255,0.85) 0%, transparent 100%), radial-gradient(2px 2px at 85% 8%, rgba(255,255,255,0.70) 0%, transparent 100%), radial-gradient(2px 2px at 92% 55%, rgba(255,255,255,0.78) 0%, transparent 100%), radial-gradient(3px 3px at 8% 72%, rgba(255,255,255,0.80) 0%, transparent 100%), radial-gradient(2px 2px at 50% 88%, rgba(255,255,255,0.65) 0%, transparent 100%), radial-gradient(2px 2px at 28% 94%, rgba(255,255,255,0.72) 0%, transparent 100%), radial-gradient(2px 2px at 76% 80%, rgba(255,255,255,0.68) 0%, transparent 100%), radial-gradient(2px 2px at 60% 62%, rgba(255,255,255,0.58) 0%, transparent 100%), radial-gradient(4px 4px at 44% 35%, rgba(200,215,240,0.60) 0%, transparent 100%), radial-gradient(3px 3px at 90% 40%, rgba(210,200,235,0.55) 0%, transparent 100%);
  pointer-events: none;
  z-index: 0;
}

/* ══════════════════════════════════
   § 布局骨架
══════════════════════════════════ */
body {
  background-color: transparent;
  color: var(--text-100);
}

#sheld {
  height: calc(100dvh - var(--topBarBlockSize) + 1px);
  max-height: calc(100dvh - var(--topBarBlockSize) + 1px);
}

#chat {
  max-height: calc(100vh - calc(var(--topBarBlockSize) + var(--bottomFormBlockSize)) + 1px);
  background: transparent;
  border: none !important;
  backdrop-filter: none;
}

#form_sheld {
  position: absolute;
  bottom: 0;
  margin: 0;
  transition: position 0s;
}

#sheld:has(#send_textarea:not(:placeholder-shown)) #form_sheld {
  position: relative;
}

.last_mes {
  margin-bottom: 120px !important;
}

#sheld:has(#send_textarea:not(:placeholder-shown)) .last_mes {
  margin-bottom: 50px !important;
}

.switch_input_type_icon {
  margin-top: 1.5cqh;
}

#world_popup {
  width: 100%;
  background: transparent !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
}

.world_entry_form .flex-container.wide100p.flexGap10 span,
.world_entry_form .fa-xs {
  place-self: center;
}

.world_entry_form .fa-xs {
  line-height: unset;
}

/* ══════════════════════════════════
   § 消息外层
══════════════════════════════════ */
.mes {
  align-items: center !important;
  width: 100%;
  padding: 6px 0;
  margin: 10px 0 20px;
  flex-direction: column !important;
  overflow: visible !important;
  border: none !important;
}

.mes_block {
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 0 !important;
  min-height: 64px;
  background: transparent !important;
}

/* ══════════════════════════════════
   § 消息文本气泡 — 日间奶白液态玻璃
══════════════════════════════════ */
.mes_text {
  width: 95%;
  overflow: visible !important;
  padding: 30px;
  margin: 0 0 12px;
  line-height: 1.7;
  font-size: unset;
  background-color: var(--SmartThemeBotMesBlurTintColor) !important;
  backdrop-filter: blur(calc(var(--SmartThemeBlurStrength))) !important;
  -webkit-backdrop-filter: blur(calc(var(--SmartThemeBlurStrength))) !important;
  border-radius: 22px;
  border: 0.5px solid rgba(255, 255, 255, 0.3);
  color: var(--text-100);
  box-shadow: inset 0 0 0 0.5px rgba(255, 255, 255, 0.3), 0 4px 12px rgba(0,0,0,0.05), 0 1px 3px rgba(0,0,0,0.02) !important;
}

/* 用户气泡 — 浅玫粉 */
.mes[is_user="true"] .mes_text {
  background: var(--SmartThemeUserMesBlurTintColor) !important;
  border-color: rgba(180,140,160,0.15) !important;
  box-shadow: inset 0 0 0 0.5px rgba(255, 255, 255, 0.3), 0 4px 12px rgba(0,0,0,0.05), 0 1px 3px rgba(0,0,0,0.02) !important;
}

/* ══════════════════════════════════
    § iOS 播放器核心容器 (Grid 重构)
══════════════════════════════════ */
.mesAvatarWrapper {
  display: grid !important;
  grid-template-columns: 82px 1fr;
  grid-template-rows: auto auto auto;
  column-gap: 16px;
  row-gap: 2px;
  align-items: center;
  position: relative;
  margin: 8px auto !important;
  padding: 16px 20px !important;
  width: 95% !important;
  max-width: 420px;
  background-color: var(--SmartThemeBotMesBlurTintColor) !important;
  backdrop-filter: blur(calc(var(--SmartThemeBlurStrength))) !important;
  -webkit-backdrop-filter: blur(calc(var(--SmartThemeBlurStrength))) !important;
  border-radius: 28px;
  border: 0.5px solid rgba(255, 255, 255, 0.5);
  box-shadow: inset 0 0 0 0.5px rgba(255, 255, 255, 0.3), 0 4px 12px rgba(0,0,0,0.05), 0 1px 3px rgba(0,0,0,0.02);
}

.mesAvatarWrapper::after {
  position: absolute;
  top: 15px;
  right: 15px;
  content: "";
  display: block;
  width: 32px;
  height: 32px;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 36 36' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M 24.72 23.72 A 9.5 9.5 0 1 0 11.28 23.72' stroke='%231d1d1f' stroke-width='1.5' fill='none' stroke-linecap='round'/%3E%3Cpath d='M 22.6 21.6 A 6.5 6.5 0 1 0 13.4 21.6' stroke='%231d1d1f' stroke-width='1.5' fill='none' stroke-linecap='round'/%3E%3Cpath d='M 20.47 19.47 A 3.5 3.5 0 1 0 15.53 19.47' stroke='%231d1d1f' stroke-width='1.5' fill='none' stroke-linecap='round'/%3E%3Cpolygon points='18,20 11,27 25,27' fill='%231d1d1f'/%3E%3C/svg%3E");
  background-repeat: no-repeat;
  background-size: contain;
  background-position: center;
  opacity: 0.3;
}

.mes[is_user="true"] .mesAvatarWrapper {
  background: var(--SmartThemeUserMesBlurTintColor) !important;
}

.avatar,
.avatar img {
  border: none !important;
  box-shadow: 0 1px 8px rgba(0,0,0,0.15) !important;
}

.mesAvatarWrapper .avatar {
  grid-column: 1;
  grid-row: 1 / span 3;
  aspect-ratio: 200 / 300;
  width: 88px !important;
  height: auto !important;
  flex-shrink: 0 !important;
  border-radius: 12px !important;
  overflow: hidden !important;
  transition: transform 0.3s cubic-bezier(0.2, 0.8, 0.2, 1) !important;
}

.mesAvatarWrapper .avatar img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
}

.mes.smallSysMes .mesAvatarWrapper {
  display: none !important;
  height: unset !important;
  min-height: unset !important;
}

/* ══════════════════════════════════
    § 1. 曲名 — 标签置左
══════════════════════════════════ */
.mesIDDisplay {
  grid-column: 2;
  display: flex;
  flex-direction: row;
  align-items: baseline;
  justify-content: center;
  gap: 7px;
  color: #1d1d1f !important;
  font-size: 16px !important;
  font-weight: 700 !important;
  padding: 0;
}

.mesIDDisplay::before {
  content: "曲名";
  display: inline-block;
  flex-shrink: 0;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.07em;
  color: rgba(60, 60, 67, 0.72);
  background: rgba(60, 60, 67, 0.07);
  padding: 2px 5px;
  border-radius: 4px;
  line-height: 1.4;
}

/* ══════════════════════════════════
    § 2. 艺术家 — 标签置左
══════════════════════════════════ */
.tokenCounterDisplay {
  grid-column: 2;
  display: flex;
  flex-direction: row;
  align-items: baseline;
  justify-content: center;
  gap: 7px;
  color: rgba(60, 60, 67, 0.65) !important;
  font-size: 13px !important;
  font-weight: 500 !important;
  padding: 0;
}

.tokenCounterDisplay::before {
  content: "艺术家";
  display: inline-block;
  flex-shrink: 0;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.07em;
  color: rgba(60, 60, 67, 0.68);
  background: rgba(60, 60, 67, 0.07);
  padding: 2px 5px;
  border-radius: 4px;
  line-height: 1.4;
}

/* ══════════════════════════════════
    § 3. 进度条 + 控制按钮 — 原样保留
══════════════════════════════════ */
.mes_timer {
  grid-column: 2;
  color: rgba(60, 60, 67, 0.6) !important;
  font-size: 11px !important;
  padding: 0;
  margin-top: 4px !important;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 8px;
}

/* 进度条（40% 已播放）*/
.mes_timer::before {
  content: "";
  height: 4px;
  width: 100%;
  border-radius: 2px;
  background: rgba(0, 0, 0, 0.06);
  background-image: linear-gradient(to right, #555 40%, transparent 40%);
}

/* ⏮ ⏸ ⏭ 控制按钮 */
.mes_timer::after {
  content: "";
  display: block;
  width: 200px;
  height: 30px;
  margin: 0 auto;
  background-image: url("data:image/svg+xml,%3Csvg%20viewBox%3D'0%200%20160%2040'%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%3E%3Cpath%20d%3D'M%2027.50%2C15.50%20Q%2027.5%2C12%2024.46%2C13.74%20L%2016.54%2C18.26%20Q%2013.5%2C20%2016.54%2C21.74%20L%2024.46%2C26.26%20Q%2027.5%2C28%2027.50%2C24.50%20Z'%20fill%3D'%231d1d1f'%2F%3E%3Cpath%20d%3D'M%2040.50%2C15.50%20Q%2040.5%2C12%2037.46%2C13.74%20L%2029.54%2C18.26%20Q%2026.5%2C20%2029.54%2C21.74%20L%2037.46%2C26.26%20Q%2040.5%2C28%2040.50%2C24.50%20Z'%20fill%3D'%231d1d1f'%2F%3E%3Crect%20x%3D'71'%20y%3D'9'%20width%3D'7.5'%20height%3D'22'%20rx%3D'1.5'%20fill%3D'%231d1d1f'%2F%3E%3Crect%20x%3D'81.5'%20y%3D'9'%20width%3D'7.5'%20height%3D'22'%20rx%3D'1.5'%20fill%3D'%231d1d1f'%2F%3E%3Cpath%20d%3D'M%20119.50%2C15.50%20Q%20119.5%2C12%20122.54%2C13.74%20L%20130.46%2C18.26%20Q%20133.5%2C20%20130.46%2C21.74%20L%20122.54%2C26.26%20Q%20119.5%2C28%20119.50%2C24.50%20Z'%20fill%3D'%231d1d1f'%2F%3E%3Cpath%20d%3D'M%20132.50%2C15.50%20Q%20132.5%2C12%20135.54%2C13.74%20L%20143.46%2C18.26%20Q%20146.5%2C20%20143.46%2C21.74%20L%20135.54%2C26.26%20Q%20132.5%2C28%20132.50%2C24.50%20Z'%20fill%3D'%231d1d1f'%2F%3E%3C%2Fsvg%3E");
  background-repeat: no-repeat;
  background-size: contain;
  background-position: center;
}

/* ══════════════════════════════════
   § 名字行 — 名字在时间戳之前
══════════════════════════════════ */
.ch_name {
  width: 100%;
  display: flex;
  margin-bottom: 2px;
  flex-direction: row;
  flex-wrap: wrap !important;
  align-items: center !important;
  gap: 6px 8px !important;
  justify-content: flex-start !important;
}

.mes .mes_block .ch_name.flex-container.justifySpaceBetween {
  flex-direction: row !important;
  align-items: center !important;
  justify-content: flex-start !important;
  gap: 8px !important;
  width: 95%;
  margin: 2px auto 6px !important;
  padding: 0 4px;
}

.mes .name_text {
  display: inline-flex;
  position: relative;
  gap: 5px;
  order: 1;
  flex-shrink: 1 !important;
  align-items: center !important;
  padding: 5px 12px !important;
  border-radius: 15px;
  font-size: 13px !important;
  font-weight: 700 !important;
  letter-spacing: 0.55px !important;
  text-transform: uppercase !important;
  background-color: rgba(255,255,255,0.70);
  backdrop-filter: blur(5px);
  -webkit-backdrop-filter: blur(5px);
  border: 0.5px solid rgba(0,0,0,0.08);
  color: var(--text-45) !important;
  box-shadow: inset 0 0.5px 0 rgba(255,255,255,0.75), 0 1px 4px rgba(0,0,0,0.06);
  z-index: 2;
}

.mes .name_text::before {
  content: "";
  display: inline-block;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background-color: var(--ios-teal);
  box-shadow: 0 0 6px rgba(56,168,108,0.55);
  flex-shrink: 0;
}

.mes[is_user="true"] .name_text {
  background: rgba(255,248,251,0.75) !important;
  border-color: rgba(180,140,160,0.16) !important;
  color: rgba(120,80,100,0.55) !important;
  box-shadow: inset 0 0.5px 0 rgba(255,255,255,0.75), 0 1px 4px rgba(160,100,120,0.06) !important;
}

.mes[is_user="true"] .name_text::before {
  background: var(--user-rose) !important;
  box-shadow: 0 0 6px rgba(160,120,138,0.50) !important;
}

/* ══════════════════════════════════
   § Timestamp — iOS 26 液态玻璃小胶囊
══════════════════════════════════ */
.small.timestamp,
.timestamp {
  order: 2;
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  background-color: rgba(242, 242, 247, 0.88);
  backdrop-filter: blur(5px);
  -webkit-backdrop-filter: blur(5px);
  border: 0.5px solid rgba(255, 255, 255, 0.72);
  border-radius: 13px;
  padding: 5px 10px !important;
  font-size: 11px !important;
  font-weight: 600 !important;
  color: rgba(60, 60, 67, 0.72) !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.98), 0 2px 8px rgba(0, 0, 0, 0.07);
  white-space: nowrap;
  flex-shrink: 0;
}

.small.timestamp::before,
.timestamp::before {
  content: "";
  display: inline-block;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background-color: rgba(60, 60, 67, 0.28);
  flex-shrink: 0;
}

.mes[is_user="true"] .timestamp {
  background-color: rgba(255, 245, 248, 0.90) !important;
  border-color: rgba(220, 170, 190, 0.35) !important;
  color: rgba(140, 80, 110, 0.78) !important;
}

.mes[is_user="true"] .timestamp::before {
  background-color: rgba(180, 120, 148, 0.32) !important;
}

svg.timestamp-icon {
  order: 3;
  flex-shrink: 0 !important;
}

/* ══════════════════════════════════
   § 编辑按钮
══════════════════════════════════ */
.mes_buttons,
.mes_edit_buttons {
  order: 4;
  flex-shrink: 0 !important;
  margin-left: auto !important;
}

.mes_buttons {
  align-self: flex-end !important;
}

.mes_edit,
.extraMesButtonsHint {
  background: var(--glass-strong) !important;
  backdrop-filter: blur(5px) !important;
  -webkit-backdrop-filter: blur(5px) !important;
  border: 1px solid var(--gb-default);
  border-radius: 50%;
  color: transparent !important;
  width: 30px !important;
  height: 30px !important;
  position: relative;
  box-shadow: inset 0 2px 4px rgba(255,255,255,0.70), 0 2px 4px rgba(0,0,0,0.07) !important;
}

.mes_block .extraMesButtons {
  align-items: center;
}

.mes_edit_buttons {
  background: var(--glass-strong) !important;
  border-radius: 28px !important;
  border: 0.5px solid rgba(255, 255, 255, 0.10) !important;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.1), inset 0 0 0 0.5px rgba(255, 255, 255, 0.06) !important;
  backdrop-filter: blur(5px) !important;
  -webkit-backdrop-filter: blur(5px) !important;
  padding: 2px 5px !important;
  filter: none;
}

.mes_edit_buttons .menu_button,
.mes_reasoning_actions .edit_button {
  opacity: 0.8;
}

.mes_reasoning_edit_done,
.mes_edit_done.menu_button {
  background-color: #B2D4ED;
}

.mes_edit:hover,
.extraMesButtonsHint:hover {
  background: var(--glass-strong) !important;
  transform: scale(1.1);
}

.mes_edit::after {
  content:"✏︎";
  position:absolute;
  font-size:14px;
  top:50%;
  left:50%;
  transform:translate(-50%,-50%);
  color:var(--text-70);
  letter-spacing:1px;
}

.extraMesButtonsHint::after {
  content:"···";
  position:absolute;
  font-size:16px;
  font-weight:900;
  top:50%;
  left:50%;
  transform:translate(-50%,-50%);
  color:var(--text-70);
  letter-spacing:1px;
}

.mes_button,
.extraMesButtons>div {
  cursor: pointer;
  transition: opacity var(--animation-duration-2x) ease-in-out;
  filter: none;
  opacity: 0.7;
  padding: 1px 3px;
}

.extraMesButtons {
  background-color: rgba(255,255,255,0.70) !important;
  padding: 2px !important;
  place-self: center;
  border-radius: 15px;
  color: var(--text-70);
}

.xiaobaix-collapse-btn {
  width: 28px !important;
  height: 28px !important;
  box-shadow: none !important;
}

/* ══════════════════════════════════
   § 推理模块 — 折叠头部 (控制中心 Widget 风)
══════════════════════════════════ */
.mes_reasoning_summary {
  position: relative !important;
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  min-height: 30px !important;
  height: fit-content;
  width: 100% !important;
  margin-bottom: 10px !important;
}

.mes_reasoning_actions {
  position: absolute !important;
  right: 5px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  margin-top: 10px !important;
  background: rgba(255, 255, 255, 0.25) !important;
