}

#options_button::after {
  content:"⚡";
  position:absolute;
  top:50%;
  left:50%;
  transform:translate(-50%,-50%);
}

#extensionsMenuButton::after {
  content:"🔧";
  position:absolute;
  top:50%;
  left:50%;
  transform:translate(-50%,-50%);
}

