  pointer-events: none;
  position: absolute;
  position-anchor: --textarea-anchor;
  left: anchor(--textarea-anchor left);
  right: anchor(--textarea-anchor right);
  top: anchor(--textarea-anchor top);
  bottom: anchor(--textarea-anchor bottom);
