/* ══════════════════════════════════
    § iOS 灵动风格加载动画 - Music Edition
══════════════════════════════════ */
#load-spinner,
#load-spinner.fa-spin {
  animation: none !important;
  -webkit-animation: none !important;
  transform: none !important;
  visibility: visible !important;
}

#load-spinner {
  --spinner-size: 60px;
  width: var(--spinner-size);
  height: var(--spinner-size);
  background-image: none !important;
  position: relative;
}

#load-spinner::before {
  content:"";
  position:absolute;
  top:50%;
  left:50%;
  width:44px;
  height:44px;
  margin:-22px 0 0 -22px;
  border-radius:50%;
  border:2.5px solid transparent;
  border-top-color: var(--ios-blue);
  border-right-color: rgba(74,133,187,0.24);
  animation: iospin 0.80s linear infinite;
  box-shadow: 0 0 14px rgba(74,133,187,0.22);
}

@keyframes iospin {
  0% {
    transform:rotate(0deg)
  }
  100% {
    transform:rotate(360deg)
  }
}

.splash-logo {
  opacity: 0 !important;
  width: 100px !important;
  height: 100px !important;
}

#loader.splash-screen::before {
  content: "♫";
  font-size: 50px;
  position: absolute;
  top: 35%;
  left: 50%;
  transform: translate(-50%, -50%);
  color: var(--ios-blue, #007AFF);
  font-family: "SF Pro Display", "Helvetica Neue", sans-serif;
  animation: music-pulse 2s ease-in-out infinite;
  text-shadow: 0 0 20px rgba(0, 122, 255, 0.2);
}

@keyframes music-pulse {
  0%,
  100% {
    transform: translate(-50%, -50%) scale(0.9);
    opacity: 0.6;
  }
  50% {
    transform: translate(-50%, -50%) scale(1.1);
    opacity: 1;
  }
}

.splash-message {
  font-size: 0 !important;
  visibility: hidden;
}

.splash-message::before {
  content: "Checking Library...";
  visibility: visible !important;
  font-size: 16px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: #8E8E93 !important;
  display: block;
  text-align: center;
  letter-spacing: -0.02em;
  margin-top: 50px;
  white-space: nowrap;
  animation: ios-text-breathe 2.5s ease-in-out infinite !important;
}

@keyframes ios-text-breathe {
  0%,
  100% {
    opacity: 0.4;
  }
  50% {
    opacity: 1;
  }
}

